package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

// scorePolicy returns a score for a candidate under the named profile.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
		} else if withinQuota {
			base += 20
		}
		base -= float64(cr) * 30

	case "standard":
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		if withinQuota {
			base += 5
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
		case "burning":
			base -= 20
		case "healthy":
			base += 10
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			base -= float64(cand.QuotaPercentUsed-80) * 2
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
	}

	// Observation-derived perf bias.
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		base += cand.ObservedTokensPerSec / 100.0
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		base += 1000.0 / cand.ObservedLatencyMS
	}
	if cand.CostClass == "experimental" {
		base -= 75
	}

	return base
}

		// Build CatalogRef map from ranked list.
		catalogRefMap := make(map[string]string, len(discovery.Ranked))
		for _, sm := range discovery.Ranked {
			if sm.CatalogRef != "" {
				catalogRefMap[sm.ID] = sm.CatalogRef
			}
		}

		for _, id := range discovery.IDs {
			info := ModelInfo{
				ID:              id,
				Provider:        providerName,
				ProviderType:    providerType,
				Harness:         "fiz",
				EndpointName:    discovery.EndpointName,
				EndpointBaseURL: discovery.EndpointBaseURL,
				ServerInstance:  discovery.ServerInstance,
				Available:       true,
			}

			// Resolve context length: provider config > provider API > catalog > default.
			info.ContextLength, info.ContextSource = resolveContextEvidence(ctx, entry, id, cat)

			// Capabilities from provider type.
			info.Capabilities = providerCapabilities(entry)

			// CatalogRef from ranked discovery.
			info.CatalogRef = catalogRefMap[id]

			// Cost and PerfSignal from catalog.
			if cat != nil && info.CatalogRef != "" {
				info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
				info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
			} else if cat != nil {
				// Try direct model lookup by ID even without a catalog ref.
				info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
				info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
			}

			// IsDefault: provider is default AND this model is the configured default model.
			info.IsDefault = isDefaultProvider && configuredDefaultModel != "" && id == configuredDefaultModel

			// RankPosition from discovery ranking.
			if pos, ok := rankPos[id]; ok {
				info.RankPosition = pos
			} else {
				info.RankPosition = -1
			}

			out = append(out, info)
		}
	}
	return out
}

type discoveredModelSet struct {
	EndpointName    string
	EndpointBaseURL string
	ServerInstance  string
	IDs             []string
	Ranked          []scoredModel
}

// discoverAndRankModels fetches the model list from each provider endpoint and
// ranks results against the catalog. IDs preserve discovery order per endpoint.
func discoverAndRankModels(ctx context.Context, entry ServiceProviderEntry, cat *modelcatalog.Catalog) []discoveredModelSet {
	switch normalizeServiceProviderType(entry.Type) {
	case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "rapid-mlx", "vllm", "ollama", "minimax", "qwen", "zai":
		endpoints := modelDiscoveryEndpoints(entry)
		if len(endpoints) == 0 {
			return nil
		}
		out := make([]discoveredModelSet, 0, len(endpoints))
		for _, endpoint := range endpoints {
			ids, err := discoverModelsInline(ctx, endpoint.BaseURL, entry.APIKey)
			if err != nil || len(ids) == 0 {
				continue
			}
			out = append(out, discoveredModelSet{
				EndpointName:    endpoint.Name,
				EndpointBaseURL: endpoint.BaseURL,
				ServerInstance:  endpoint.ServerInstance,
				IDs:             ids,
				Ranked:          rankModelsInline(ids, cat),
			})
		}
		return out

	case "anthropic":
		// Anthropic does not expose /v1/models for discovery.
		// If a default model is configured, surface it.
		if entry.Model != "" {
			sm := scoredModel{ID: entry.Model, CatalogRef: "", RankPosition: 0}
			if cat != nil {
				if ref, ok := catalogRefForModel(cat, entry.Model); ok {
					sm.CatalogRef = ref
				}
			}
			return []discoveredModelSet{{
				EndpointName:    "default",
				EndpointBaseURL: entry.BaseURL,
				ServerInstance:  serverinstance.Normalize(entry.BaseURL, entry.ServerInstance),
				IDs:             []string{entry.Model},
				Ranked:          []scoredModel{sm},
			}}
		}
		return nil

	default:
		return nil
	}
}

type modelDiscoveryEndpoint struct {
	Name           string
	BaseURL        string
	ServerInstance string
}

func modelDiscoveryEndpoints(entry ServiceProviderEntry) []modelDiscoveryEndpoint {
	if len(entry.Endpoints) > 0 {
		out := make([]modelDiscoveryEndpoint, 0, len(entry.Endpoints))
		for _, ep := range entry.Endpoints {
			if strings.TrimSpace(ep.BaseURL) == "" {
				continue
			}
			out = append(out, modelDiscoveryEndpoint{
				Name:           endpointDisplayName(ep.Name, ep.BaseURL),
				BaseURL:        ep.BaseURL,
				ServerInstance: serverinstance.Normalize(ep.BaseURL, ep.ServerInstance),
			})
		}
		return out
	}
	if strings.TrimSpace(entry.BaseURL) == "" {
		return nil
	}
	return []modelDiscoveryEndpoint{{
		Name:           endpointDisplayName("default", entry.BaseURL),
		BaseURL:        entry.BaseURL,
		ServerInstance: serverinstance.Normalize(entry.BaseURL, entry.ServerInstance),
	}}
}

func endpointDisplayName(name, baseURL string) string {
	if trimmed := strings.TrimSpace(name); trimmed != "" {
		return trimmed
	}
	u, err := url.Parse(baseURL)
	if err == nil && u.Host != "" {
		return u.Host
	}
	return "default"
}

// discoverModelsInline queries /v1/models and returns model IDs.
// Mirrors the inline impl in service_providers.go to avoid import cycle.
func discoverModelsInline(ctx context.Context, baseURL, apiKey string) ([]string, error) {
	base := strings.TrimRight(baseURL, "/")
	endpoint := base + "/models"

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("discovery: build request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
		return nil, fmt.Errorf("discovery: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}

	var mr struct {
		Data []struct {
			ID string `json:"id"`
		} `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil {
		return nil, fmt.Errorf("discovery: decode response: %w", err)
	}

	ids := make([]string, 0, len(mr.Data))
	for _, m := range mr.Data {
		if m.ID != "" {
			ids = append(ids, m.ID)
		}
	}
	return ids, nil
}

// scoredModel mirrors provider/openai.ScoredModel to avoid the import cycle.
type scoredModel struct {
	ID           string
	CatalogRef   string
	RankPosition int
}

// rankModelsInline scores discovered model IDs against the catalog.
func rankModelsInline(ids []string, cat *modelcatalog.Catalog) []scoredModel {
	var knownModels map[string]string
	if cat != nil {
		knownModels = cat.AllConcreteModels(modelcatalog.SurfaceAgentOpenAI)
	}

	// Score: 3=catalog, 2=pattern(unused here), 1=uncategorized.
	scored := make([]scoredModel, 0, len(ids))
	for pos, id := range ids {
		sm := scoredModel{ID: id, RankPosition: pos}
		if ref, ok := knownModels[id]; ok {
			sm.CatalogRef = ref
		}
		scored = append(scored, sm)
	}
	return scored
}

// catalogRefForModel looks up a model ID in the catalog and returns (targetID, true) if found.
func catalogRefForModel(cat *modelcatalog.Catalog, modelID string) (string, bool) {
	knownModels := cat.AllConcreteModels(modelcatalog.SurfaceAgentOpenAI)
	ref, ok := knownModels[modelID]
	return ref, ok
}

// resolveContextEvidence resolves the context window for a model using the
// precedence chain: provider config > provider API > catalog > default.
func resolveContextEvidence(ctx context.Context, entry ServiceProviderEntry, modelID string, cat *modelcatalog.Catalog) (int, string) {
	modelID = strings.TrimSpace(modelID)
	if modelID == "" {
		return 0, ContextSourceUnknown
	}
	if entry.ContextWindow > 0 {
		return entry.ContextWindow, ContextSourceProviderConfig
	}
	if limits, source := providerAPIContextEvidence(ctx, entry, modelID); limits > 0 {
		return limits, source
	}
	if cat != nil {
		if n := cat.ContextWindowForModel(modelID); n > 0 {
			return n, ContextSourceCatalog
		}
	}
	return compaction.DefaultContextWindow, ContextSourceDefault
}

func providerAPIContextEvidence(ctx context.Context, entry ServiceProviderEntry, modelID string) (int, string) {
	switch entry.Type {
	case "lmstudio":
		if entry.BaseURL == "" {
			return 0, ""
		}
		if limits := lmstudio.LookupModelLimits(ctx, entry.BaseURL, modelID); limits.ContextLength > 0 {
			return limits.ContextLength, ContextSourceProviderAPI
		}
	case "omlx":
		if entry.BaseURL == "" {
			return 0, ""
		}
		if limits := omlx.LookupModelLimits(ctx, entry.BaseURL, modelID); limits.ContextLength > 0 {
			return limits.ContextLength, ContextSourceProviderAPI
		}
	case "openrouter":
		if entry.BaseURL == "" {
			return 0, ""
		}
		if limits := openrouter.LookupModelLimits(ctx, entry.BaseURL, entry.APIKey, entry.Headers, modelID); limits.ContextLength > 0 {
			return limits.ContextLength, ContextSourceProviderAPI
		}
	}
	return 0, ""
}

// catalogCostAndPerf extracts CostInfo and PerfSignal for a model from the catalog.
func catalogCostAndPerf(cat *modelcatalog.Catalog, modelID string) (CostInfo, PerfSignal) {
	entry, ok := cat.LookupModel(modelID)
	if ok {
		return CostInfo{
				InputPerMTok:  catalogEntryInputCost(entry),
				OutputPerMTok: catalogEntryOutputCost(entry),
			}, PerfSignal{
				SpeedTokensPerSec: entry.SpeedTokensPerSec,
				SWEBenchVerified:  entry.SWEBenchVerified,
			}
	}

	// Fallback: try target-level pricing via PricingFor.
	pricing := cat.PricingFor()
	if p, ok := pricing[modelID]; ok {
		return CostInfo{
			InputPerMTok:  p.InputPerMTok,
			OutputPerMTok: p.OutputPerMTok,
		}, PerfSignal{}

